import Model from 'flarum/common/Model';
/** A story, as Api\StoryResource serializes it for the person looking. */
export default class Story extends Model {
  kind = Model.attribute('kind');
  text = Model.attribute('text');
  background = Model.attribute('background');
  caption = Model.attribute('caption');
  linkUrl = Model.attribute('linkUrl');
  audience = Model.attribute('audience');
  status = Model.attribute('status');
  createdAt = Model.attribute('createdAt', Model.transformDate);
  expiresAt = Model.attribute('expiresAt', Model.transformDate);
  mediaUrl = Model.attribute('mediaUrl');
  mediaType = Model.attribute('mediaType');
  width = Model.attribute('width');
  height = Model.attribute('height');
  durationMs = Model.attribute('durationMs');
  isSeen = Model.attribute('isSeen');
  myReaction = Model.attribute('myReaction');
  authorFollowed = Model.attribute('authorFollowed');
  viewCount = Model.attribute('viewCount');
  reactionCount = Model.attribute('reactionCount');
  canDelete = Model.attribute('canDelete');
  canModerate = Model.attribute('canModerate');
  canReact = Model.attribute('canReact');
  canReport = Model.attribute('canReport');
  canSeeViewers = Model.attribute('canSeeViewers');
  user = Model.hasOne('user');
  mentionedUsers = Model.hasMany('mentionedUsers');
}
flarum.reg.add('ernestdefoe-glimpse', 'forum/models/Story', Story);